class Account:
    def __init__(self, balance):
        self._balance = balance      # "protected" by convention

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, value):
        if value < 0:
            raise ValueError("Balance can't be negative")
        self._balance = value

